import {controlStyles,applyControlStyle} from './control-styles.js';
import {readingFonts} from './device-tools.js';
import {applyTheme,resolvedMode} from './themes.js';
import {uid} from './core.js';
// Platform presentation uses device information locally; it is never transmitted.
export const platformNames={auto:'Match my device',...Object.fromEntries(Object.entries(controlStyles).map(([id,style])=>[id,style.name]))};
export function detectPlatform(nav=globalThis.navigator){const platform=nav?.userAgentData?.platform||nav?.platform||'';const ua=nav?.userAgent||'';if(/android/i.test(platform+' '+ua))return 'android';if(/iPhone|iPad|iPod|Mac/i.test(platform+' '+ua))return 'apple';if(/Win/i.test(platform+' '+ua))return 'windows';if(/Linux|X11|CrOS/i.test(platform+' '+ua))return 'linux';return 'bookwiz';}
export function applyAppearance(settings,root=document.documentElement){const media=q=>globalThis.matchMedia?.(q).matches??globalThis.window?.matchMedia?.(q).matches??false;const nativePlatform=({ios:'apple',android:'android',darwin:'apple',win32:'windows',linux:'linux'})[globalThis.window?.BookWizHost?.platform];const platform=nativePlatform||(Object.hasOwn(platformNames,settings.platform)&&settings.platform!=='auto'?settings.platform:detectPlatform());root.dataset.platform=platform;root.dataset.edition=globalThis.window?.BookWizHost?'app':'web';const mode=resolvedMode(settings,media);root.classList.toggle('dark',mode==='dark');applyTheme(settings,root,mode);applyControlStyle(platform,root);root.classList.toggle('reduce-transparency',!!settings.reduceTransparency||media('(prefers-reduced-transparency: reduce)'));root.classList.toggle('reduce-motion',!!settings.reduceMotion||media('(prefers-reduced-motion: reduce)'));root.classList.toggle('sidebar-collapsed',!!settings.sidebarCollapsed);root.style.setProperty('--reading-font',readingFonts[settings.readingFont]||readingFonts.Lora);root.style.setProperty('--editor-size',(settings.font||19)+'px');return platform;}
export function addRevision(p,c,reason='Saved version',now=Date.now(),{includeEmpty=false}={}){if(!c||typeof c.text!=='string'||!includeEmpty&&!c.text.trim())return false;p.revisions??=[];if(c.text.length>400000)return false;const prev=p.revisions.find(r=>r.chapterId===c.id);if(prev?.text===c.text&&prev?.title===c.title)return false;p.revisions.unshift({id:uid(),chapterId:c.id,index:p.chapters.indexOf(c),title:c.title,text:c.text,date:now,reason});let total=0;p.revisions=p.revisions.filter((r,i)=>{total+=r.text.length;return i<12&&total<=400000;});return true;}
export function searchWorkspace(projects,input){const query=String(input).trim().toLocaleLowerCase();if(!query)return [];const results=[];for(const p of projects){if(p.title.toLocaleLowerCase().includes(query))results.push({kind:'book',id:p.id,title:p.title,detail:p.archived?'Archived book':p.genre});for(let i=0;i<p.chapters.length;i++){const c=p.chapters[i],text=c.text.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ');if((c.title+' '+text).toLocaleLowerCase().includes(query)){const n=text.toLocaleLowerCase().indexOf(query);results.push({kind:'chapter',id:p.id,index:i,title:c.title,detail:p.title+' · '+(n>=0?text.slice(Math.max(0,n-30),n+85):'Chapter')});}}for(const [field,kind]of [['characters','character'],['bible','world'],['notes','note']])for(const entity of p[field]||[]){const text=Object.values(entity).join(' ');if(text.toLocaleLowerCase().includes(query))results.push({kind,id:p.id,title:entity.name||String(entity.text).slice(0,65),detail:p.title});}}return results.slice(0,35);}
